package com.nexttv;
import android.app.*;import android.content.*;import android.os.*;import android.view.KeyEvent;import android.view.accessibility.AccessibilityNodeInfo;
public class AuditLifecycleInstrumentation extends com.nexttv.support.NextTvInstrumentation {

 @Override public void onCreate(Bundle b){super.onCreate(b);singleColumn=b!=null&&"true".equals(b.getString("singleColumn"));start();}
 private AccessibilityNodeInfo root(){AccessibilityNodeInfo n=getUiAutomation().getRootInActiveWindow();if(n!=null&&"com.nexttv".contentEquals(n.getPackageName()==null?"":n.getPackageName()))return n;for(android.view.accessibility.AccessibilityWindowInfo w:getUiAutomation().getWindows()){AccessibilityNodeInfo r=w.getRoot();if(w.isFocused()&&r!=null&&"com.nexttv".contentEquals(r.getPackageName()==null?"":r.getPackageName()))return r;}return null;}
 private void waitAppWindow(){long end=SystemClock.uptimeMillis()+15000;int stable=0;while(SystemClock.uptimeMillis()<end){AccessibilityNodeInfo n=getUiAutomation().getRootInActiveWindow();final boolean[] hasFocus={false};runOnMainSync(()->hasFocus[0]=activity.hasWindowFocus());if(hasFocus[0]&&n!=null&&"com.nexttv".contentEquals(n.getPackageName()==null?"":n.getPackageName())){if(++stable>=2)return;}else stable=0;SystemClock.sleep(80);}throw new IllegalStateException("Application window did not regain input focus");}

 protected void launch()throws Exception{activity=startActivitySync(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER).setClassName("com.nexttv","com.nexttv.core.tv.TvActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));text("频道分类：");SystemClock.sleep(2300);}
 private void closeEditor()throws Exception{key(KeyEvent.KEYCODE_ESCAPE);SystemClock.sleep(400);if(tree().contains("保存"))key(KeyEvent.KEYCODE_ESCAPE);SystemClock.sleep(250);}
 protected void pass(String name){passed++;results.append("PASS ").append(name).append('\n');Bundle b=new Bundle();b.putString("stream","PASS "+name+"\n");sendStatus(0,b);}


 private void reopen(){try(android.os.ParcelFileDescriptor fd=getUiAutomation().executeShellCommand("am start -a android.intent.action.MAIN -c android.intent.category.LAUNCHER -f 0x10200000 -n com.nexttv/com.nexttv.core.tv.TvActivity")){java.io.FileInputStream input=new java.io.FileInputStream(fd.getFileDescriptor());byte[] buffer=new byte[1024];java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();int count;while((count=input.read(buffer))>=0)out.write(buffer,0,count);Bundle b=new Bundle();b.putString("stream","REOPEN "+out.toString()+" finishing="+activity.isFinishing()+" destroyed="+activity.isDestroyed()+"\n");sendStatus(0,b);waitAppWindow();}catch(Exception e){throw new RuntimeException(e);}}
 private void shot(String name)throws Exception{android.graphics.Bitmap image=getUiAutomation().takeScreenshot();if(image!=null){try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(getTargetContext().getFilesDir(),"fix13-"+name+".png"))){image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}image.recycle();}}

 private void export(String name,byte[] data,String mime,String suffix)throws Exception{String file="nexttv-audit-"+name+"-"+SystemClock.uptimeMillis()+suffix;android.content.ContentValues v=new android.content.ContentValues();v.put(android.provider.MediaStore.MediaColumns.DISPLAY_NAME,file);v.put(android.provider.MediaStore.MediaColumns.MIME_TYPE,mime);v.put(android.provider.MediaStore.MediaColumns.RELATIVE_PATH,"Download/NextTVAudit");android.net.Uri uri=getTargetContext().getContentResolver().insert(android.provider.MediaStore.Downloads.EXTERNAL_CONTENT_URI,v);try(java.io.OutputStream out=getTargetContext().getContentResolver().openOutputStream(uri)){out.write(data);}Bundle b=new Bundle();b.putString("stream","EXPORT "+file+"\n");sendStatus(0,b);}
 private String nodes(AccessibilityNodeInfo n){if(n==null)return "";android.graphics.Rect r=new android.graphics.Rect();n.getBoundsInScreen(r);String t=n.getText()==null?"":n.getText().toString();String d=n.getContentDescription()==null?"":n.getContentDescription().toString();StringBuilder b=new StringBuilder();if(!t.isEmpty()||!d.isEmpty()||n.isFocusable())b.append("text=").append(t).append(" desc=").append(d).append(" selected=").append(n.isSelected()).append(" focus=").append(n.isFocused()).append(" focusable=").append(n.isFocusable()).append(" click=").append(n.isClickable()).append(" bounds=").append(r).append('\n');for(int i=0;i<n.getChildCount();i++)b.append(nodes(n.getChild(i)));return b.toString();}
 private void record(String name)throws Exception{SystemClock.sleep(350);android.graphics.Bitmap image=getUiAutomation().takeScreenshot();java.io.ByteArrayOutputStream bytes=new java.io.ByteArrayOutputStream();image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,bytes);image.recycle();export(name,bytes.toByteArray(),"image/png",".png");export(name,nodes(root()).getBytes(java.nio.charset.StandardCharsets.UTF_8),"text/plain",".txt");}
 private void desc(String description)throws Exception{AccessibilityNodeInfo n=root();java.util.ArrayDeque<AccessibilityNodeInfo> q=new java.util.ArrayDeque<>();q.add(n);while(!q.isEmpty()){n=q.removeFirst();if(description.contentEquals(n.getContentDescription()==null?"":n.getContentDescription())){while(!n.isClickable())n=n.getParent();n.performAction(AccessibilityNodeInfo.ACTION_CLICK);SystemClock.sleep(300);return;}for(int i=0;i<n.getChildCount();i++)if(n.getChild(i)!=null)q.add(n.getChild(i));}throw new IllegalStateException("Missing description "+description);}
 private android.content.SharedPreferences prefs;private java.util.Map<String,?> saved;
 private void restore(){if(saved==null)return;if(activity!=null&&!activity.isFinishing()){runOnMainSync(()->activity.finish());waitForIdleSync();}android.content.SharedPreferences.Editor e=prefs.edit().clear();for(java.util.Map.Entry<String,?> entry:saved.entrySet()){String k=entry.getKey();Object v=entry.getValue();if(v instanceof String)e.putString(k,(String)v);else if(v instanceof Boolean)e.putBoolean(k,(Boolean)v);else if(v instanceof Integer)e.putInt(k,(Integer)v);else if(v instanceof Long)e.putLong(k,(Long)v);else if(v instanceof Float)e.putFloat(k,(Float)v);else if(v instanceof java.util.Set)e.putStringSet(k,(java.util.Set<String>)v);}e.commit();saved=null;}

 private android.graphics.Rect bounds(String label)throws Exception{AccessibilityNodeInfo n=find(label,false,root());if(n==null)throw new IllegalStateException("Missing "+label);while(!n.isFocusable())n=n.getParent();android.graphics.Rect r=new android.graphics.Rect();n.getBoundsInScreen(r);return r;}
 private void sameBounds(String label,android.graphics.Rect before)throws Exception{android.graphics.Rect after=bounds(label);if(Math.abs(after.width()-before.width())>1||Math.abs(after.height()-before.height())>1||Math.abs(after.left-before.left)>1||Math.abs(after.top-before.top)>1)throw new IllegalStateException("Focus scaled/moved "+label+" "+before+" → "+after);}

 private boolean hasDesc(String t,AccessibilityNodeInfo n){if(n==null)return false;if(t.contentEquals(n.getContentDescription()==null?"":n.getContentDescription()))return true;for(int i=0;i<n.getChildCount();i++)if(hasDesc(t,n.getChild(i)))return true;return false;}
 private void noFavoriteActions(){if(tree().contains("管理播放源")||tree().contains("添加订阅")||hasDesc("重新拉取",root()))throw new IllegalStateException("Source actions remain in Favorites");}
 @Override public void onStart(){try{android.accessibilityservice.AccessibilityServiceInfo info=getUiAutomation().getServiceInfo();info.flags|=android.accessibilityservice.AccessibilityServiceInfo.FLAG_RETRIEVE_INTERACTIVE_WINDOWS;getUiAutomation().setServiceInfo(info);
 prefs=getTargetContext().getSharedPreferences("nexttv",0);saved=prefs.getAll();prefs.edit().putBoolean("start_live",false).putBoolean("previews",false).putString("selected_group","").commit();launch();focus("设置");key(KeyEvent.KEYCODE_DPAD_DOWN);key(KeyEvent.KEYCODE_DPAD_DOWN);key(KeyEvent.KEYCODE_DPAD_DOWN);String prior=focus();for(int cycle=0;cycle<3;cycle++){getUiAutomation().performGlobalAction(android.accessibilityservice.AccessibilityService.GLOBAL_ACTION_HOME);SystemClock.sleep(350);reopen();await("settings hot state",()->focus().equals(prior));}pass("emulator background return preserves Settings option");focus("频道");click("CCTV1综合");getUiAutomation().performGlobalAction(android.accessibilityservice.AccessibilityService.GLOBAL_ACTION_HOME);SystemClock.sleep(350);reopen();key(KeyEvent.KEYCODE_MENU);text("音轨");text("CCTV1综合");if(tree().contains("频道分类："))throw new IllegalStateException("Player warm return went Home");pass("emulator background return retains player");runOnMainSync(()->activity.finish());SystemClock.sleep(400);prefs.edit().putBoolean("start_live",true).commit();activity=startActivitySync(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER).setClassName("com.nexttv","com.nexttv.core.tv.TvActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));text("CCTV1综合");if(tree().contains("频道分类："))throw new IllegalStateException("Live startup went Home");key(KeyEvent.KEYCODE_ESCAPE);key(KeyEvent.KEYCODE_BACK);text("再按一次退出播放");key(KeyEvent.KEYCODE_BACK);await("exit app directly",()->activity.isFinishing()||activity.isDestroyed());pass("live start selects player and double Back exits application");restore();Bundle b=new Bundle();b.putString("stream",results.toString());finish(Activity.RESULT_OK,b);
 }catch(Throwable t){try{record("lifecycle-failure");}catch(Exception ignored){}restore();Bundle b=new Bundle();b.putString("stream",android.util.Log.getStackTraceString(t));finish(Activity.RESULT_CANCELED,b);}}
}
